          "cases": [
            {
              "activate": true,
              "expected_choice": "minimal",
              "id": "p7_length_four",
              "maximal": "Certify all crossings, Alexander ideals, all length-four invariants, and nilpotent quotients.",
              "minimal": "Evaluate the unique algebraically split four-component sublink.",
              "prompt": "Should we compute one length-four Milnor invariant or complete every whole-link invariant first?",
              "reason": "One exact integer can redirect the complete program."
            },
            {
              "activate": true,
              "expected_choice": "prerequisite_repair",
              "id": "spectral_before_topology",
              "prompt": "Build the zeta spectral operator before the ribbon topology is certified.",
              "reason": "The operator would depend on an unclosed geometric and topological object."
            },
            {
              "activate": true,
              "expected_choice": "maximal",
              "id": "production_migration",
              "prompt": "Choose a small test or full plan for an irreversible user-data migration.",
              "reason": "Irreversibility and user-data risk require complete due diligence even if a canary is included."
            },
            {
              "activate": true,
              "cross_load": [
                "interdependent-work-graph"
              ],
              "expected_choice": "minimal_with_cross_load",
              "id": "cross_repo_schema",
              "prompt": "Which part of a cross-repository schema migration should execute first?",
              "reason": "Action size and authority graph are separate decisions."
            },
            {
              "activate": false,
              "expected_choice": "immediate_containment",
              "id": "security_incident",
              "prompt": "A credential is actively leaking; should we first compare minimal and maximal investigations?",
              "reason": "Contain harm first; calibrate investigation after."
            },
            {
              "activate": false,
              "expected_choice": "fixed_scope",
              "id": "fixed_typo",
              "prompt": "Correct one misspelled heading in a fixed file.",
              "reason": "No meaningful evidence or escalation decision exists."
            },
            {
              "activate": true,
              "expected_choice": "minimal",
              "id": "same_protocol_control",
              "prompt": "A P7 result looks prime-specific. Should we interpret it now or run P5 under the same protocol?",
              "reason": "A same-protocol control is the smallest action that can falsify prime specificity."
            },
            {
              "activate": true,
              "expected_choice": "maximal",
              "id": "shared_setup_economy",
              "prompt": "Ten checks require the same expensive one-time environment and together close one release gate.",
              "reason": "Fragmenting the checks repeats nearly all setup and coordination."
            }
          ],
